log_user 0
set timeout 10
set out ""
proc rec {s} { global out; append out $s "\n" }
proc signum {n} { array set m {SIGHUP 1 SIGINT 2 SIGKILL 9 SIGTERM 15}; return $m($n) }
proc status {w} {
    if {[llength $w] > 4 && [lindex $w 4] eq "CHILDKILLED"} { return [expr {128 + [signum [lindex $w 5]]}] }
    return [lindex $w 3]
}
proc finish {} { global out; set f [open out w]; puts -nonewline $f $out; flush $f; exit 0 }
# Every expect call passes its patterns and actions as separate arguments (no single braced list), so
# expect(1)'s one-argument brace heuristic and a preceding -timeout flag cannot turn the list into a pattern.
spawn /usr/bin/python3 alt2.py
after 500
expect -re {alpha} { rec "rc=0 which=0 match=$expect_out(0,string)" } \
       -re {beta} { rec "rc=0 which=1 match=$expect_out(0,string)" } \
       timeout { rec "rc=1" } eof { rec "rc=2" }
expect -re {zzz} { rec "rc=0 which=0 match=$expect_out(0,string)" } \
       -re {id=[0-9]+} { rec "rc=0 which=1 match=$expect_out(0,string)" } \
       timeout { rec "rc=1" } eof { rec "rc=2" }
send "go\n"
expect -re {split-ok} { rec "split rc=0 match=$expect_out(0,string)" } timeout { rec "split rc=1" } eof { rec "split rc=2" }
expect -re {mark1} { rec "mark=0" } timeout { rec "mark=1" } eof { rec "mark=2" }
after 600
set t0 [clock milliseconds]
expect -timeout 0 -re {late-token} { rec "ready-bytes=0" } timeout { rec "ready-bytes=1" } eof { rec "ready-bytes=2" }
expect -timeout 0 -re {never-printed} { rec "absent=0" } timeout { rec "absent=1" } eof { rec "absent=2" }
if {[clock milliseconds] - $t0 < 500} { rec "no-wait" } else { rec "waited" }
send "quit\n"
expect eof { rec "eof=0" } timeout { rec "eof=1" }
catch {close}
rec "close=[status [wait]]"
finish

