# Every expect call passes its patterns and actions as separate arguments (no single braced list), so
# expect(1)'s one-argument brace heuristic and a preceding -timeout flag cannot turn the list into a pattern.
spawn /usr/bin/python3 rt.py dialog
set pid [exp_pid]
set info none
expect -re {leader=[a-z]+ ctty=[a-z]+ pid=[0-9]+\r} { set info [string trimright $expect_out(0,string) "\r"] } \
       timeout { rec "info=1" } eof { rec "info=2" }
set cp none
regexp {pid=([0-9]+)} $info -> cp
if {$cp == $pid} { rec "pid-is-child" } else { rec "pid-differs" }
regsub { pid=[0-9]+$} $info "" short
rec $short
expect -re {name\? $} { rec "prompt=\[$expect_out(0,string)\]" } timeout { rec "prompt=1" } eof { rec "prompt=2" }
send "alice\n"
expect -re {alice\r\ngot='[^']*'} { rec "echo-and-reply=[string map [list \r <CR> \n <LF>] $expect_out(0,string)]" } \
       timeout { rec "echo-and-reply=1" } eof { rec "echo-and-reply=2" }
expect -re {cmd\? $} { rec "cmd=0" } timeout { rec "cmd=1" } eof { rec "cmd=2" }
send "bob\r"
expect -re {got2='[^']*'} { rec $expect_out(0,string) } timeout { rec "got2=1" } eof { rec "got2=2" }
set r unset
expect -re {never-printed} { set r 0 } timeout { set r 1 } eof { set r 2 }
rec "expect-at-eof=$r"
catch {close}; rec "close=[status [wait]]"
if {[file exists /proc/$pid]} { rec "child-present" } else { rec "child-gone" }
spawn /usr/bin/python3 rt.py killself
set pid [exp_pid]
expect -re {ready} { rec "kill-ready=0" } timeout { rec "kill-ready=1" } eof { rec "kill-ready=2" }
expect eof { rec "kill-eof=0" } timeout { rec "kill-eof=1" }
catch {close}; rec "kill-close=[status [wait]]"
if {[file exists /proc/$pid]} { rec "child-present" } else { rec "child-gone" }
spawn /usr/bin/python3 rt.py linger
set pid [exp_pid]
expect -re {ready} { rec "hup-ready=0" } timeout { rec "hup-ready=1" } eof { rec "hup-ready=2" }
set t0 [clock milliseconds]
catch {close}; set st [status [wait]]
rec "hup-close=$st"
if {[clock milliseconds] - $t0 < 10000} { rec "close-did-not-wait" } else { rec "close-waited" }
if {[file exists /proc/$pid]} { rec "child-present" } else { rec "child-gone" }
finish

