import os, pty, select, sys
# Independent transcript encoder: a trusted python3 driver runs the same three-prompt dialog with tr.py on its
# own pty (pty.fork: new session, the pty as controlling terminal, default termios) and records the bytes it
# reads and writes, writing '<<<\n' / '>>>\n' on each direction change. Logging stops before the third
# exchange, as the candidate case does with 'expect log FD off'.
pid, fd = pty.fork()
if pid == 0:
    os.execv('/usr/bin/python3', ['/usr/bin/python3', 'tr.py'])
log, last, buf, logging = open('log-a', 'wb'), None, b'', True
def rec(d, data):
    global last
    if logging and data:
        if d != last:
            log.write(b'<<<\n' if d == '<' else b'>>>\n'); last = d
        log.write(data)
def wait_for(pat):
    global buf
    while pat not in buf:
        if not select.select([fd], [], [], 10)[0]:
            sys.exit('timeout waiting for %r' % pat)
        try:
            d = os.read(fd, 256)
        except OSError:
            d = b''
        if not d:
            sys.exit('eof waiting for %r' % pat)
        rec('<', d); buf += d
def send(data):
    os.write(fd, data); rec('>', data)
wait_for(b'p1> '); send(b'one\n'); wait_for(b'p2> '); send(b'two\n'); wait_for(b'p3> ')
logging = False
send(b'three\n'); wait_for(b'reply:three')
while True:
    try:
        if not os.read(fd, 256):
            break
    except OSError:
        break
_, st = os.waitpid(pid, 0)
log.close()
open('done', 'w').write('exit=%d\n' % os.waitstatus_to_exitcode(st))
